const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const palmSpringsPoint = ee.Geometry.Point([-116.5453, 33.8303]); // Approximate center of Palm Springs
  const startDate = '2017-06-15';
  const endDate = '2017-06-22'; // Filter up to, but not including, the end date

  // 2. Data Acquisition & Check
  let era5Collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(palmSpringsPoint)
    .select('temperature_2m'); // Select 2m air temperature

  const collectionSize = await era5Collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No ERA5-Land hourly data found for the specified date range and location.");
    console.log("C1");
    return;
  }

  // Function to convert Kelvin to Fahrenheit
  const kelvinToFahrenheit = function(image) {
    // T(°F) = (T(K) - 273.15) × 9/5 + 32
    return image.expression(
      '(temp - 273.15) * 9/5 + 32',
      {temp: image.select('temperature_2m')}
    ).rename('temperature_fahrenheit')
    .copyProperties(image, ['system:time_start']); // Keep time property for reference
  };

  // Apply the conversion to the collection
  const fahrenheitCollection = era5Collection.map(kelvinToFahrenheit);

  // 3. Processing: Find the maximum temperature in Fahrenheit
  const maxTempImage = fahrenheitCollection.max();

  // Reduce the maximum temperature image over the Palm Springs point
  // Use a small scale because ERA5-Land is already coarse (0.1 degree or approx 9km)
  const maxTempFahrenheit = await maxTempImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: palmSpringsPoint,
    scale: 9000, // ERA5-Land resolution is ~9km, use this scale
    maxPixels: 1e9
  }).get('temperature_fahrenheit').getInfo();

  // 4. Validation & Final Answer
  if (maxTempFahrenheit === null || isNaN(maxTempFahrenheit)) {
    console.log("Calculation failure: Maximum temperature could not be determined.");
    console.log("C3");
    return;
  }

  console.log(`ERA5-Land Images: ${collectionSize}`);
  console.log(`Max temperature in Palm Springs between ${startDate} and ${endDate}: ${maxTempFahrenheit.toFixed(2)} °F`);

  const targetTemp = 115;
  if (maxTempFahrenheit >= targetTemp) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
